function LogoutPage({onConfirm,onCancel}){return <div className="logout-page"><div className="logout-card"><div className="logout-mark"><LogOut size={25}/></div><div className="eyebrow">SMART MESS · ACCOUNT</div><h1>Sign out?</h1><p>You’re about to sign out of your Smart Mess account. You’ll need to sign in again to access the dashboard.</p><button className="primary logout-confirm" onClick={onConfirm}><LogOut size={16}/>Sign out</button><button className="logout-cancel" onClick={onCancel}>Stay signed in</button><small>Your campus data stays saved on this device.</small></div></div>}
const studentLinks=[['My overview','/student',LayoutDashboard],['Weekly menu','/student/menu',Utensils],['My attendance','/student/attendance',ClipboardList],['My payments','/student/payments',CreditCard],['Feedback','/student/feedback',Star],['Complaints','/student/complaints',MessageSquare],['My profile','/student/profile',Users]];
function StudentPortal({user,onLogout}){const location=useLocation(),navigate=useNavigate();const defaultPayments=[{"id":"FEE-NOV-2026","period":"November 2026","amount":4500,"status":"Pending"},{"id":"FEE-OCT-2026","period":"October 2026","amount":4500,"status":"Paid"},{"id":"FEE-SEP-2026","period":"September 2026","amount":4500,"status":"Paid"}];const [checkins,setCheckins]=useState([]);const [payments,setPayments]=useState(defaultPayments);const [complaints,setComplaints]=useState([]);const [feedback,setFeedback]=useState([]);const [toastMsg,setToastMsg]=useState('');const [portalLoaded,setPortalLoaded]=useState(false);const notify=(m)=>{setToastMsg(m);setTimeout(()=>setToastMsg(''),3500)};const savePortal=(key,value)=>apiRequest('/api/student/portal',{method:'PUT',body:{data:{[key]:value}}}).catch(error=>notify(error.message));useEffect(()=>{let live=true;apiRequest('/api/student/portal').then(({data})=>{if(!live)return;setCheckins(data.checkins||[]);setPayments(data.payments?.length?data.payments:defaultPayments);setComplaints(data.complaints||[]);setFeedback(data.feedback||[]);setPortalLoaded(true);if(!data.payments?.length)savePortal('payments',defaultPayments)}).catch(error=>{if(live){setPortalLoaded(true);notify(error.message)}});return()=>{live=false}},[user.id]);const logout=()=>{setApiToken(null);onLogout()};const title=studentLinks.find(x=>x[1]===location.pathname)?.[0]||'My overview';const page=location.pathname;const dayName=new Intl.DateTimeFormat('en-US',{weekday:'long'}).format(new Date());const menu=seed.menu.find(m=>m.day===dayName)||seed.menu[0];const markPresent=meal=>{const next=[{meal,date:new Date().toLocaleDateString('en-IN'),time:new Date().toLocaleTimeString('en-IN',{hour:'2-digit',minute:'2-digit'}),status:'Present'},...checkins];setCheckins(next);savePortal('checkins',next);notify(`${meal} attendance checked in`)};const pay=payment=>{const next=payments.map(p=>p.id===payment.id?{...p,status:'Paid'}:p);setPayments(next);savePortal('payments',next);notify('Payment confirmed and saved')};const submitLocal=(e,key,list,setList,storage,build)=>{e.preventDefault();const form=new FormData(e.currentTarget);const item=build(form);const next=[item,...list];setList(next);savePortal(key,next);e.currentTarget.reset();notify('Submitted successfully')};return <div className="student-app"><Toaster position="top-right"/><aside className="student-sidebar"><div className="brand"><div className="brand-icon"><Sparkles size={20}/></div><div><b>SMART<span>MESS</span></b><small>STUDENT PORTAL</small></div></div><div className="student-campus"><span className="ws-dot"/> IIIT Bhubaneswar</div><div className="nav-label">MY MESS</div><nav>{studentLinks.map(([label,path,Icon])=><NavLink end={path==='/student'} to={path} key={path} className={({isActive})=>'nav-link '+(isActive?'selected':'')}><Icon size={17}/><span>{label}</span></NavLink>)}</nav><div className="student-side-bottom"><div className="student-user"><div className="avatar">{user.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</div><div><b>{user.name}</b><small>Student · {user.email}</small></div></div><button className="nav-link student-logout" onClick={()=>navigate('/student/logout')}><LogOut size={17}/><span>Logout</span></button></div></aside><main className="student-main"><header className="student-topbar"><div><span>Student portal</span><b>/ {title}</b></div><div className="student-top-user"><span>{user.name}</span><div className="avatar">{user.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</div></div></header><div className="student-content">{page==='/student/logout'?<div className="logout-page"><div className="logout-card"><div className="logout-mark"><LogOut size={25}/></div><div className="eyebrow">STUDENT ACCOUNT</div><h1>Sign out?</h1><p>You’ll need to sign in again to access your student portal.</p><button className="primary logout-confirm" onClick={logout}><LogOut size={16}/>Sign out</button><button className="logout-cancel" onClick={()=>navigate('/student')}>Stay signed in</button></div></div>:<><PageHead eyebrow="IIIT BHUBANESWAR · STUDENT PORTAL" title={page==='/student'?`Hi, ${user.name.split(' ')[0]} 👋`:title} sub={page==='/student'?"Your mess, meals, and membership at a glance.":`Manage your ${title.toLowerCase()} information.`}/>{page==='/student'&&<><div className="stat-grid student-stats">{[['Subscription','Active','Renews Dec 1'],['Attendance this month','92%','23 of 25 meals'],['Current balance','₹4,500','November mess fee'],['Meal rating','4.6 / 5','Your campus average']].map(([a,b,c],i)=><div className="stat-card" key={a}><div className="stat-top"><span>{a}</span></div><div className="stat-value">{b}</div><div className="stat-bottom"><span>{c}</span></div></div>)}</div><div className="student-columns"><div className="panel student-meals"><div className="panel-head"><div><h3>Today’s menu</h3><p>{dayName} · served fresh every day</p></div><NavLink to="/student/menu" className="text-button">Full menu <ArrowUpRight size={14}/></NavLink></div>{[['Breakfast',menu.breakfast,'7:30 AM'],['Lunch',menu.lunch,'12:30 PM'],['Snacks',menu.snacks,'4:30 PM'],['Dinner',menu.dinner,'7:00 PM']].map(([a,b,c])=><div className="student-meal-row" key={a}><div><b>{a}</b><small>{c}</small></div><span>{b}</span></div>)}</div><div className="panel student-quick"><h3>Quick actions</h3><p>Take care of the little things</p><NavLink to="/student/attendance"><QrCode size={17}/>Check in for a meal<ArrowUpRight size={14}/></NavLink><NavLink to="/student/complaints"><MessageSquare size={17}/>Report an issue<ArrowUpRight size={14}/></NavLink><NavLink to="/student/feedback"><Star size={17}/>Rate a meal<ArrowUpRight size={14}/></NavLink></div></div></>}{page==='/student/menu'&&<div className="student-menu-grid">{seed.menu.map(m=><div className="panel student-menu-day" key={m.day}><div className="eyebrow">WEEKLY MENU</div><h3>{m.day}</h3>{[['Breakfast',m.breakfast],['Lunch',m.lunch],['Snacks',m.snacks],['Dinner',m.dinner]].map(([a,b])=><div className="student-menu-row" key={a}><b>{a}</b><span>{b}</span></div>)}</div>)}</div>}{page==='/student/attendance'&&<><div className="panel checkin-card"><div><div className="eyebrow">TODAY’S CHECK-IN</div><h2>Enjoying a meal?</h2><p>Check in when you arrive at the dining hall. Demo check-ins save to this browser.</p></div><div className="checkin-buttons">{['Breakfast','Lunch','Dinner'].map(m=><button className="primary" key={m} onClick={()=>markPresent(m)}><QrCode size={15}/>{m}</button>)}</div></div><div className="panel table-panel student-table"><div className="table-toolbar"><div><h3>My recent attendance</h3><p>Your recorded meal visits</p></div></div><div className="table-scroll"><table><thead><tr><th>MEAL</th><th>DATE</th><th>TIME</th><th>STATUS</th></tr></thead><tbody>{checkins.map((x,i)=><tr key={i}><td>{x.meal}</td><td>{x.date}</td><td>{x.time}</td><td><span className="badge green"><i/>{x.status}</span></td></tr>)}</tbody></table>{!checkins.length&&<div className="student-empty">No check-ins yet. Use the buttons above to record a demo check-in.</div>}</div></div></>}{page==='/student/payments'&&<div className="panel table-panel student-table"><div className="table-toolbar"><div><h3>Mess fee history</h3><p>Monthly fee · ₹4,500</p></div></div><div className="table-scroll"><table><thead><tr><th>INVOICE</th><th>PERIOD</th><th>AMOUNT</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody>{payments.map(p=><tr key={p.id}><td className="mono">{p.id}</td><td>{p.period}</td><td><b>₹{p.amount.toLocaleString('en-IN')}</b></td><td><span className={`badge ${p.status==='Paid'?'green':'orange'}`}><i/>{p.status}</span></td><td>{p.status==='Pending'?<button className="primary pay-demo" onClick={()=>pay(p)}>Pay now</button>:<button className="secondary pay-demo" onClick={()=>notify(`Receipt for ${p.period} downloaded`)}><Download size={13}/>Receipt</button>}</td></tr>)}</tbody></table></div></div>}{page==='/student/feedback'&&<div className="student-form-layout"><form className="panel student-form" onSubmit={e=>submitLocal(e,'feedback',feedback,setFeedback,'smart-mess-student-feedback',f=>({id:'FB-'+Date.now(),meal:f.get('meal'),rating:Number(f.get('rating')),comment:f.get('comment'),date:new Date().toLocaleDateString('en-IN')}))}><h3>Rate your meal</h3><p>Help the mess team keep improving.</p><label className="form-field">Meal<select name="meal"><option>Breakfast</option><option>Lunch</option><option>Snacks</option><option>Dinner</option></select></label><label className="form-field">Rating<select name="rating"><option value="5">★★★★★ — Excellent</option><option value="4">★★★★ — Good</option><option value="3">★★★ — Okay</option><option value="2">★★ — Needs improvement</option><option value="1">★ — Poor</option></select></label><label className="form-field">Comment<textarea name="comment" required minLength="3" placeholder="What did you think about the meal?"/></label><button className="primary">Submit feedback</button></form><div className="panel student-form"><h3>Your feedback</h3><p>Previous ratings you’ve sent</p>{feedback.length?feedback.map((f,i)=><div className="student-history" key={i}><b>{f.meal} · {'★'.repeat(f.rating)}</b><span>{f.comment}</span><small>{f.date}</small></div>):<div className="student-empty">Your submitted feedback will appear here.</div>}</div></div>}{page==='/student/complaints'&&<div className="student-form-layout"><form className="panel student-form" onSubmit={e=>submitLocal(e,'complaints',complaints,setComplaints,'smart-mess-student-complaints',f=>({id:`STU-${Date.now().toString().slice(-6)}`,category:f.get('category'),priority:f.get('priority'),message:f.get('message'),status:'Pending',date:new Date().toLocaleDateString('en-IN')}))}><h3>Raise a complaint</h3><p>We’ll share your concern with the mess administrator.</p><label className="form-field">Category<select name="category"><option>Food Quality</option><option>Hygiene</option><option>Staff Behaviour</option><option>Menu Issues</option><option>Other</option></select></label><label className="form-field">Priority<select name="priority"><option>Low</option><option>Medium</option><option>High</option></select></label><label className="form-field">What happened?<textarea name="message" minLength="5" required placeholder="Describe the issue"/></label><button className="primary">Submit complaint</button></form><div className="panel student-form"><h3>Complaint history</h3><p>Track your submitted concerns</p>{complaints.length?complaints.map(c=><div className="student-history" key={c.id}><div><b>{c.category}</b><span className="badge orange"><i/>{c.status}</span></div><span>{c.message}</span><small>{c.date}</small></div>):<div className="student-empty">Your complaint history will appear here.</div>}</div></div>}{page==='/student/profile'&&<div className="panel student-profile-panel"><div className="avatar big">{user.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</div><h2>{user.name}</h2><p>{user.email}</p><div className="drawer-fields">{[['Student ID','IIITB24101'],['Department','CSE'],['Hostel','Aryabhatta'],['Room','2011'],['Subscription','Active'],['Monthly mess fee','₹4,500']].map(([a,b])=><div key={a}><span>{a}</span><b>{b}</b></div>)}</div></div>}</>}</div></main>{toastMsg&&<div className="student-toast">{toastMsg}</div>}</div>}
function AuthPage({mode,onAuth}){const [register,setRegister]=useState(mode==='register');const [error,setError]=useState('');const [show,setShow]=useState(false);const [values,setValues]=useState({name:'',email:'',password:'',role:'student'});const goRegister=()=>{setRegister(true);setError('');history.pushState({},'', '/register')};const goLogin=()=>{setRegister(false);setError('');history.pushState({},'', '/login')};const submit=async e=>{e.preventDefault();const email=values.email.trim().toLowerCase();try{const result=register?await apiRequest('/api/auth/register',{method:'POST',auth:false,body:{name:values.name.trim(),email,password:values.password}}):await apiRequest('/api/auth/login',{method:'POST',auth:false,body:{email,password:values.password}});onAuth(result)}catch(error){setError(error.message)}};return <div className="auth-screen"><div className="auth-art"><div className="auth-brand"><div className="brand-icon"><Sparkles size={20}/></div><div><b>SMART<span>MESS</span></b><small>IIIT BHUBANESWAR</small></div></div><div className="auth-orbit orbit-one"/><div className="auth-orbit orbit-two"/><div className="auth-orbit orbit-three"/><div className="auth-art-copy"><span className="auth-pill"><span className="ws-dot"/> CAMPUS OPERATIONS, REIMAGINED</span><h1>Better meals.<br/><em>Smarter campus.</em></h1><p>One thoughtful platform for a better dining experience at IIIT Bhubaneswar.</p><div className="auth-proof"><div className="proof-avatars"><i>AS</i><i>AD</i><i>RM</i><i>+</i></div><span><b>850+ students</b><small>one connected campus</small></span></div></div><div className="auth-art-foot">BUILT FOR IIIT BHUBANESWAR <span>·</span> 20.2961° N, 85.8245° E</div></div><div className="auth-form-side"><div className="auth-mobile-brand"><div className="brand-icon"><Sparkles size={20}/></div><b>SMART<span>MESS</span></b></div><form className="auth-card" onSubmit={submit}><div className="eyebrow">{register?'GET STARTED':'WELCOME BACK'}</div><h2>{register?'Create your account':'Sign in to Smart Mess'}</h2><p>{register?'Join the IIIT Bhubaneswar mess management workspace.':'Your campus, running a little smarter.'}</p>{error&&<div className="auth-error"><AlertCircle size={14}/>{error}</div>}{register&&<label className="auth-field">Full name<div><Users size={16}/><input required minLength="2" placeholder="Your name" value={values.name} onChange={e=>setValues({...values,name:e.target.value})}/></div></label>}{register&&<div className="auth-field"><span>Account type</span><div className="role-chip">Student portal · Admin accounts are provisioned by your administrator</div></div>}<label className="auth-field">Email address<div><MessageSquare size={16}/><input type="email" required placeholder="you@iiit-bh.ac.in" value={values.email} onChange={e=>setValues({...values,email:e.target.value})}/></div></label><label className="auth-field">Password<div><Settings size={16}/><input type={show?'text':'password'} required minLength="10" placeholder="At least 10 characters" value={values.password} onChange={e=>setValues({...values,password:e.target.value})}/><button type="button" onClick={()=>setShow(!show)}>{show?'Hide':'Show'}</button></div></label>{!register&&<div className="auth-options"><label><input type="checkbox" defaultChecked/> Remember me</label><button type="button" onClick={()=>toast('Contact your mess administrator to reset your password.')}>Forgot password?</button></div>}<button className="primary auth-submit" type="submit">{register?'Create account':'Sign in'}<ArrowUpRight size={16}/></button>{!register&&<div className="demo-hint"><b>Admin access</b><span>Use the account configured by your administrator.</span></div>}<div className="auth-switch">{register?'Already have an account?':'New to Smart Mess?'} <button type="button" onClick={register?goLogin:goRegister}>{register?'Sign in':'Create an account'}</button></div><div className="auth-legal">By continuing, you agree to the campus acceptable use policy.</div></form><div className="auth-mobile-foot">© 2026 Smart Mess · IIIT Bhubaneswar</div></div></div>}
function PageHead({eyebrow,title,sub,button,onClick,extra}){return <div className="page-head"><div><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{sub}</p></div><div className="head-actions">{extra}{button&&<button className="primary" onClick={onClick}><Plus size={16}/>{button}</button>}</div></div>}
function Dashboard({data,setModal,setActive}){const stats=[['Total students','850','+4.8%','vs last month',Users,'blue'],['Active subscriptions','785','+2.1%','vs last month',Utensils,'teal'],["Today's attendance",'92%','+3.4%','vs last week',Activity,'violet'],['Monthly revenue','₹6.25L','+8.2%','vs last month',CircleDollarSign,'amber']];return <><PageHead eyebrow="TUESDAY, NOVEMBER 10, 2026" title="Good morning, Admin 👋" sub="Here’s what’s happening across your mess today." button="Add student" onClick={()=>setModal({title:'Add student',key:'students',fields:['id','name','email','phone','department','hostel','room','subscription','payment'],labels:['Student ID','Full name','Email','Phone','Department','Hostel','Room number','Subscription','Payment status']})}/><div className="stat-grid">{stats.map(([label,val,delta,period,Icon,color])=><div className="stat-card" key={label}><div className="stat-top"><span>{label}</span><div className={`stat-icon ${color}`}><Icon size={17}/></div></div><div className="stat-value">{val}</div><div className="stat-bottom"><span className="trend"><TrendingUp size={13}/>{delta}</span><span>{period}</span><div className="sparkline"><svg viewBox="0 0 84 28"><path d="M1 22 C12 21 12 13 23 17 S37 7 46 14 S59 19 68 8 S77 10 83 3"/></svg></div></div></div>)}</div><div className="chart-grid"><div className="panel large-chart"><div className="panel-head"><div><h3>Meal attendance</h3><p>Student check-ins this week</p></div><button className="select-small">This week <ChevronDown size={14}/></button></div><div className="legend"><span><i className="lg-blue"/> Present</span><span><i className="lg-gray"/> Absent</span><b>92% <small>avg. attendance</small></b></div><ResponsiveContainer width="100%" height={220}><AreaChart data={attendance} margin={{top:8,right:8,left:-22,bottom:0}}><defs><linearGradient id="pres" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#4f8cff" stopOpacity={.24}/><stop offset="100%" stopColor="#4f8cff" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#ffffff0c" vertical={false}/><XAxis dataKey="day" stroke="#7d879b" axisLine={false} tickLine={false}/><YAxis stroke="#7d879b" axisLine={false} tickLine={false}/><Tooltip contentStyle={{background:'#171d2c',border:'1px solid #2a3348',borderRadius:10}}/><Area type="monotone" dataKey="present" stroke="#4f8cff" strokeWidth={2.5} fill="url(#pres)"/><Area type="monotone" dataKey="absent" stroke="#47546a" strokeWidth={1.5} fill="transparent"/></AreaChart></ResponsiveContainer></div><div className="panel revenue-chart"><div className="panel-head"><div><h3>Revenue overview</h3><p>Monthly collections</p></div><button className="more-btn"><Ellipsis size={18}/></button></div><div className="revenue-total">₹6,25,000 <span>+8.2%</span></div><div className="revenue-caption">Collected this month</div><ResponsiveContainer width="100%" height={175}><BarChart data={revenue} margin={{top:12,right:0,left:-27,bottom:0}}><CartesianGrid stroke="#ffffff0a" vertical={false}/><XAxis dataKey="m" stroke="#7d879b" axisLine={false} tickLine={false}/><YAxis stroke="#7d879b" axisLine={false} tickLine={false}/><Tooltip contentStyle={{background:'#171d2c',border:'1px solid #2a3348',borderRadius:10}}/><Bar dataKey="v" fill="#4f8cff" radius={[5,5,0,0]} maxBarSize={20}/></BarChart></ResponsiveContainer></div></div><div className="lower-grid"><div className="panel activity-panel"><div className="panel-head"><div><h3>Recent activity</h3><p>Latest updates from your mess</p></div><button className="text-button">View all <ArrowUpRight size={14}/></button></div><div className="activity-list">{[['AN','Ananya Das','checked in for lunch','12:42 PM','blue'],['RS','Rohan Sahu','submitted a complaint','11:18 AM','violet'],['PM','Priya Mishra','payment received · ₹4,500','10:05 AM','teal'],['IK','Ishaan Kumar','rated breakfast 5 stars','9:32 AM','amber']].map(([initial,name,msg,time,col])=><div className="activity-row" key={name}><div className={`activity-avatar ${col}`}>{initial}</div><div className="activity-copy"><b>{name}</b><span>{msg}</span></div><time>{time}</time></div>)}</div></div><div className="panel quick-panel"><div className="panel-head"><div><h3>Quick actions</h3><p>Common tasks, one click away</p></div></div><div className="quick-grid">{[[Users,'Add student','blue',()=>setModal({title:'Add student',key:'students',fields:['id','name','email','department','hostel','room','subscription','payment'],labels:['Student ID','Full name','Email','Department','Hostel','Room','Subscription','Payment']})],[QrCode,'Scan attendance','teal',()=>setActive({type:'scanner'})],[Utensils,'Update menu','violet',()=>setModal({title:'Update menu item',key:'menu',fields:['day','breakfast','lunch','snacks','dinner'],labels:['Day','Breakfast','Lunch','Snacks','Dinner']})],[FileText,'Export report','amber',()=>exportCSV('mess-report.csv',[{metric:'Students',value:850},{metric:'Active subscriptions',value:785},{metric:'Monthly revenue',value:625000}])]].map(([Icon,label,col,action])=><button key={label} onClick={action}><span className={`quick-icon ${col}`}><Icon size={18}/></span>{label}<ArrowUpRight size={13}/></button>)}</div><div className="special"><div className="special-image"/><div><span>TONIGHT’S SPECIAL</span><b>Chicken curry &amp; steamed rice</b><small>Dinner · 7:00 – 9:00 PM</small></div><span className="special-spark">✦</span></div></div></div></>}
function exportCSV(name,rows){const csv=[Object.keys(rows[0]||{}).join(','),...rows.map(r=>Object.values(r).map(v=>`"${String(v).replaceAll('"','""')}"`).join(','))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download=name;a.click();URL.revokeObjectURL(a.href);toast.success('Report downloaded')}
function Students({data,setData,setModal,remove,search,setActive}){const [filter,setFilter]=useState('All students'),[page,setPage]=useState(1);const rows=data.students.filter(s=>`${s.name} ${s.id} ${s.hostel}`.toLowerCase().includes(search.toLowerCase())&&(filter==='All students'||s.subscription===filter));const per=7;const show=rows.slice((page-1)*per,page*per);const fields=['id','name','email','phone','department','hostel','room','subscription','payment'];const labels=['Student ID','Full name','Email','Phone','Department','Hostel','Room number','Subscription','Payment status'];const open=(s)=>{setActive({type:'student',...s})};return <><PageHead eyebrow="CAMPUS DIRECTORY" title="Students" sub="Manage student profiles and mess subscriptions." button="Add student" onClick={()=>setModal({title:'Add student',key:'students',fields,labels})}/><div className="stat-grid mini-stats">{[['Total students','850'],['Active subscriptions','785'],['Pending payments','45']].map(([a,b])=><div className="mini-stat" key={a}><span>{a}</span><b>{b}</b></div>)}</div><div className="panel table-panel"><div className="table-toolbar"><div><h3>Student directory <span className="pill-count">{rows.length}</span></h3><p>Student records across all hostels</p></div><div className="table-actions"><div className="local-search"><Search size={15}/><input placeholder="Search students" value={search}/></div><select value={filter} onChange={e=>{setFilter(e.target.value);setPage(1)}}><option>All students</option><option>Active</option><option>Inactive</option></select><button className="icon-button"><SlidersHorizontal size={16}/></button></div></div><div className="table-scroll"><table><thead><tr><th><input type="checkbox"/></th><th>STUDENT</th><th>STUDENT ID</th><th>DEPARTMENT</th><th>HOSTEL / ROOM</th><th>SUBSCRIPTION</th><th>PAYMENT</th><th/></tr></thead><tbody>{show.map((s,i)=><tr key={s.id}><td><input type="checkbox"/></td><td><button className="student-cell" onClick={()=>open(s)}><span className={`student-avatar ava${i%5}`}>{s.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</span><span><b>{s.name}</b><small>{s.email}</small></span></button></td><td className="mono">{s.id}</td><td>{s.department}</td><td>{s.hostel}<small className="subline">Room {s.room}</small></td><td><span className={`badge ${s.subscription==='Active'?'green':'gray'}`}><i/>{s.subscription}</span></td><td><span className={`badge ${s.payment==='Paid'?'blue':'orange'}`}><i/>{s.payment}</span></td><td><button className="row-menu" onClick={()=>open(s)}><MoreHorizontal size={18}/></button></td></tr>)}</tbody></table></div><div className="table-foot"><span>Showing {show.length?((page-1)*per+1):0}–{Math.min(page*per,rows.length)} of {rows.length} students</span><div><button disabled={page===1} onClick={()=>setPage(page-1)}><ChevronLeft size={15}/></button><button className="page-num">{page}</button><button disabled={page*per>=rows.length} onClick={()=>setPage(page+1)}><ChevronRight size={15}/></button></div></div></div></>}
function MenuPage({data,setData,setModal}){const [day,setDay]=useState('Monday');const current=data.menu.find(m=>m.day===day)||data.menu[0];return <><PageHead eyebrow="WEEKLY PLANNER" title="Mess menu" sub="Plan balanced meals for every day of the week." button="Edit weekly menu" onClick={()=>setModal({title:'Edit weekly menu',key:'menu',item:current,fields:['day','breakfast','lunch','snacks','dinner'],labels:['Day','Breakfast','Lunch','Snacks','Dinner']})}/><div className="menu-hero"><div><span className="badge blue"><i/> TODAY’S SPECIAL</span><h2>A little something to<br/>look forward to.</h2><p>Slow-cooked chicken curry, aromatic basmati rice &amp; fresh salad.</p><small>TONIGHT · DINNER · 7:00 – 9:00 PM</small></div><div className="menu-food"/></div><div className="day-tabs">{data.menu.map(m=><button className={m.day===day?'active':''} onClick={()=>setDay(m.day)} key={m.day}>{m.day}<span>{m.day==='Tuesday'?'Today':''}</span></button>)}</div><div className="meal-grid">{[['breakfast','Breakfast','7:30 – 9:30 AM','☀'],['lunch','Lunch','12:30 – 2:30 PM','◉'],['snacks','Evening snacks','4:30 – 5:30 PM','☕'],['dinner','Dinner','7:00 – 9:00 PM','☾']].map(([key,title,time,sym],i)=><div className="meal-card" key={key}><div className={`meal-photo meal${i}`}><span>{sym}</span><button title="Edit meal" onClick={()=>setModal({title:`Edit ${title.toLowerCase()}`,key:'menu',item:current,fields:['day',key],labels:['Day',title]})}><Edit3 size={15}/></button></div><div className="meal-info"><div><span>{time}</span><h3>{title}</h3></div><span className="meal-tag">{i===3?'Non-veg':'Veg friendly'}</span></div><p>{current[key]}</p></div>)}</div></>}
function Attendance(){const [meal,setMeal]=useState('All meals'),[scanned,setScanned]=useState(false);return <><PageHead eyebrow="TUESDAY, NOVEMBER 10" title="Attendance" sub="Monitor student check-ins across today’s meals." button="Scan QR code" onClick={()=>setScanned(true)}/><div className="stat-grid">{[['Present today','782','92% of students'],['Breakfast','748','88% attendance'],['Lunch','782','92% attendance'],['Dinner forecast','810','Expected tonight']].map(([a,b,c],i)=><div className="stat-card" key={a}><div className="stat-top"><span>{a}</span><div className={`stat-icon ${['blue','teal','violet','amber'][i]}`}><Users size={17}/></div></div><div className="stat-value">{b}</div><div className="stat-bottom"><span className="trend">{c}</span></div></div>)}</div><div className="chart-grid"><div className="panel large-chart"><div className="panel-head"><div><h3>Weekly attendance</h3><p>Daily check-ins across all meals</p></div><button className="select-small">This week <ChevronDown size={14}/></button></div><ResponsiveContainer width="100%" height={270}><LineChart data={attendance}><CartesianGrid stroke="#ffffff0c" vertical={false}/><XAxis dataKey="day" stroke="#7d879b" axisLine={false} tickLine={false}/><YAxis stroke="#7d879b" axisLine={false} tickLine={false}/><Tooltip contentStyle={{background:'#171d2c',border:'1px solid #2a3348',borderRadius:10}}/><Line type="monotone" dataKey="present" stroke="#4f8cff" strokeWidth={3} dot={{fill:'#4f8cff',r:4}}/></LineChart></ResponsiveContainer></div><div className="panel"><div className="panel-head"><div><h3>By meal</h3><p>Attendance distribution</p></div></div><div className="donut"><ResponsiveContainer width="100%" height={205}><PieChart><Pie data={[{name:'Breakfast',value:748},{name:'Lunch',value:782},{name:'Dinner',value:690},{name:'Snacks',value:510}]} innerRadius={58} outerRadius={83} paddingAngle={4} dataKey="value">{colors.map(c=><Cell key={c} fill={c}/>)}</Pie><Tooltip/></PieChart></ResponsiveContainer><div className="donut-label"><b>2,730</b><small>check-ins</small></div></div><div className="legend vertical">{['Breakfast','Lunch','Dinner','Snacks'].map((x,i)=><span key={x}><i style={{background:colors[i]}}/>{x}<b>{[748,782,690,510][i]}</b></span>)}</div></div></div><div className="panel table-panel"><div className="table-toolbar"><div><h3>Recent check-ins</h3><p>Live attendance log · Today</p></div><select value={meal} onChange={e=>setMeal(e.target.value)}><option>All meals</option><option>Breakfast</option><option>Lunch</option><option>Dinner</option></select></div><div className="table-scroll"><table><thead><tr><th>STUDENT</th><th>STUDENT ID</th><th>MEAL</th><th>CHECK-IN</th><th>STATUS</th></tr></thead><tbody>{['Ananya Das','Rohan Sahu','Aarav Mohanty','Meera Nair'].map((n,i)=><tr key={n}><td><b>{n}</b></td><td className="mono">IIITB2410{1+i}</td><td>{['Lunch','Lunch','Breakfast','Breakfast'][i]}</td><td>12:{['42','38','15','09'][i]} PM</td><td><span className="badge green"><i/>Checked in</span></td></tr>)}</tbody></table></div></div>{scanned&&<div className="modal-backdrop"><div className="modal scanner-modal"><button className="modal-x" onClick={()=>setScanned(false)}><X/></button><div className="scanner-icon"><QrCode size={36}/></div><h2>QR attendance scanner</h2><p>Point the scanner at a student QR code to check them in.</p><div className="scan-box"><div className="scan-line"/><QrCode size={80}/></div><button className="primary full" onClick={()=>{setScanned(false);toast.success('Aarav Mohanty checked in for lunch')}}><Check size={16}/>Simulate check-in</button><small>DEMO MODE · NO CAMERA REQUIRED</small></div></div>}</>}
function Payments({data,search}){const [filter,setFilter]=useState('All transactions');const rows=data.payments.filter(x=>x.student.toLowerCase().includes(search.toLowerCase())&&(filter==='All transactions'||x.status===filter));return <><PageHead eyebrow="FINANCE OVERVIEW" title="Payments" sub="Track monthly mess fees, collections, and outstanding dues." button="Export transactions" onClick={()=>exportCSV('mess-payments.csv',rows)}/><div className="stat-grid">{[['Total collected','₹6,25,000','This month'],['Paid students','805','94.7% of students'],['Pending payments','45','₹2,02,500 outstanding'],['Monthly fee','₹4,500','Per student']].map(([a,b,c],i)=><div className="stat-card" key={a}><div className="stat-top"><span>{a}</span><div className={`stat-icon ${['teal','blue','amber','violet'][i]}`}><CreditCard size={17}/></div></div><div className="stat-value">{b}</div><div className="stat-bottom"><span>{c}</span></div></div>)}</div><div className="panel table-panel"><div className="table-toolbar"><div><h3>Transaction history</h3><p>Recent student payments and dues</p></div><select value={filter} onChange={e=>setFilter(e.target.value)}><option>All transactions</option><option>Paid</option><option>Pending</option></select></div><div className="table-scroll"><table><thead><tr><th>TRANSACTION</th><th>STUDENT</th><th>DATE</th><th>METHOD</th><th>AMOUNT</th><th>STATUS</th><th>RECEIPT</th></tr></thead><tbody>{rows.map((p,i)=><tr key={p.id}><td className="mono">{p.id}</td><td><b>{p.student}</b></td><td>{p.date}</td><td>{p.method}</td><td><b>{currency(p.amount)}</b></td><td><span className={`badge ${p.status==='Paid'?'green':'orange'}`}><i/>{p.status}</span></td><td><button className="icon-button small" onClick={()=>{exportCSV(`${p.id}-receipt.csv`,[p]);toast.success('Receipt downloaded')}}><Download size={15}/></button></td></tr>)}</tbody></table></div></div></>}
function Complaints({data,setData,setModal}){const [filter,setFilter]=useState('All complaints');const rows=data.complaints.filter(x=>filter==='All complaints'||x.status===filter);return <><PageHead eyebrow="STUDENT VOICE" title="Complaints" sub="Listen, respond, and make the mess experience better." button="New complaint" onClick={()=>setModal({title:'Submit complaint',key:'complaints',fields:['student','category','priority','message'],labels:['Student name','Category','Priority','Describe the issue']})}/><div className="stat-grid mini-stats">{[['Open complaints',data.complaints.filter(c=>c.status!=='Resolved').length],['In progress',data.complaints.filter(c=>c.status==='In Progress').length],['Resolved this month','38']].map(([a,b])=><div className="mini-stat" key={a}><span>{a}</span><b>{b}</b></div>)}</div><div className="panel table-panel"><div className="table-toolbar"><div><h3>Complaint inbox <span className="pill-count">{rows.length}</span></h3><p>Submitted by students across campus</p></div><select value={filter} onChange={e=>setFilter(e.target.value)}><option>All complaints</option><option>Pending</option><option>In Progress</option><option>Resolved</option></select></div><div className="complaint-list">{rows.map(c=><article className="complaint-item" key={c.id}><div className={`priority-marker ${c.priority.toLowerCase()}`}/><div className="complaint-main"><div className="complaint-meta"><span className="mono">{c.id}</span><span className={`badge ${c.priority==='High'?'red':c.priority==='Medium'?'orange':'gray'}`}><i/>{c.priority} priority</span><span className="badge blue">{c.category}</span></div><h3>{c.message}</h3><p>Submitted by <b>{c.student}</b> <span>·</span> {c.date}</p>{c.response&&<div className="response"><b>Admin response</b><p>{c.response}</p></div>}</div><div className="complaint-right"><span className={`badge ${c.status==='Resolved'?'green':c.status==='In Progress'?'violet':'orange'}`}><i/>{c.status}</span><select value={c.status} onChange={e=>setData(d=>({...d,complaints:d.complaints.map(x=>x.id===c.id?{...x,status:e.target.value}:x)}))}><option>Pending</option><option>In Progress</option><option>Resolved</option></select></div></article>)}</div></div></>}
function Feedback({data,setData,setModal}){return <><PageHead eyebrow="STUDENT SENTIMENT" title="Feedback & ratings" sub="Understand how every meal is landing with students." button="Add feedback" onClick={()=>setModal({title:'Submit feedback',key:'feedback',fields:['name','meal','rating','comment'],labels:['Student name','Meal','Rating (1–5)','Comment']})}/><div className="stat-grid">{[['Average rating','4.6 / 5','Across all meals'],['Feedback this week','248','+12% from last week'],['Top rated meal','Lunch','4.8 average'],['Needs attention','Dinner','3.9 average']].map(([a,b,c],i)=><div className="stat-card" key={a}><div className="stat-top"><span>{a}</span><div className={`stat-icon ${['amber','blue','teal','violet'][i]}`}><Star size={17}/></div></div><div className="stat-value">{b}</div><div className="stat-bottom"><span>{c}</span></div></div>)}</div><div className="chart-grid"><div className="panel large-chart"><div className="panel-head"><div><h3>Food feedback ratings</h3><p>Average rating by meal this week</p></div></div><ResponsiveContainer width="100%" height={250}><BarChart data={[{meal:'Breakfast',rating:4.4},{meal:'Lunch',rating:4.8},{meal:'Snacks',rating:4.2},{meal:'Dinner',rating:3.9}]}><CartesianGrid stroke="#ffffff0c" vertical={false}/><XAxis dataKey="meal" stroke="#7d879b" axisLine={false} tickLine={false}/><YAxis domain={[0,5]} stroke="#7d879b" axisLine={false} tickLine={false}/><Tooltip contentStyle={{background:'#171d2c',border:'1px solid #2a3348',borderRadius:10}}/><Bar dataKey="rating" fill="#a979ff" radius={[6,6,0,0]}/></BarChart></ResponsiveContainer></div><div className="panel"><div className="panel-head"><div><h3>Rating snapshot</h3><p>All meal feedback</p></div></div><div className="rating-big">4.6 <span>★★★★★</span></div><p className="rating-note">Based on 1,284 student ratings</p>{[5,4,3,2,1].map((x,i)=><div className="rating-row" key={x}><span>{x} ★</span><div><i style={{width:[68,22,7,2,1][i]+'%'}}/></div><span>{[68,22,7,2,1][i]}%</span></div>)}</div></div><div className="panel feedback-panel"><div className="panel-head"><div><h3>Recent feedback</h3><p>What students are saying</p></div></div><div className="feedback-grid">{data.feedback.map(f=><div className="feedback-card" key={f.name}><div className="feedback-top"><div className="activity-avatar blue">{f.name.split(' ').map(x=>x[0]).join('')}</div><div><b>{f.name}</b><small>{f.meal} · {f.date}</small></div><span>{'★'.repeat(f.rating)}<i>{'★'.repeat(5-f.rating)}</i></span></div><p>“{f.comment}”</p></div>)}</div></div></>}
function Inventory({data,setData,setModal,remove}){return <><PageHead eyebrow="KITCHEN OPERATIONS" title="Inventory" sub="Keep every ingredient accounted for and the kitchen running smoothly." button="Add item" onClick={()=>setModal({title:'Add inventory item',key:'inventory',fields:['name','category','qty','unit','threshold','supplier','cost'],labels:['Item name','Category','Quantity','Unit','Low stock threshold','Supplier','Unit cost (₹)']})}/><div className="stat-grid">{[['Inventory items',data.inventory.length,'Across 5 categories'],['Estimated stock value',currency(data.inventory.reduce((a,x)=>a+x.qty*x.cost,0)),'Current stock'],['Low stock alerts',data.inventory.filter(x=>x.qty<x.threshold).length,'Items need reordering'],['Food wastage','18.4 kg','This week · ↓ 12%']].map(([a,b,c],i)=><div className="stat-card" key={a}><div className="stat-top"><span>{a}</span><div className={`stat-icon ${['blue','teal','amber','violet'][i]}`}><Package size={17}/></div></div><div className="stat-value">{b}</div><div className="stat-bottom"><span>{c}</span></div></div>)}</div><div className="panel table-panel"><div className="table-toolbar"><div><h3>Stock overview</h3><p>Raw materials and supplier details</p></div><button className="select-small" onClick={()=>toast('Showing all stock categories')}>All categories <ChevronDown size={14}/></button></div><div className="table-scroll"><table><thead><tr><th>ITEM</th><th>CATEGORY</th><th>IN STOCK</th><th>STOCK LEVEL</th><th>SUPPLIER</th><th>UNIT COST</th><th/></tr></thead><tbody>{data.inventory.map((x,i)=><tr key={x.name}><td><b>{x.name}</b></td><td>{x.category}</td><td><b>{x.qty} {x.unit}</b></td><td><div className="stock-bar"><i className={x.qty<x.threshold?'low':''} style={{width:Math.min(100,x.qty/(x.threshold*2)*100)+'%'}}/></div><small>{x.qty<x.threshold?'Low stock':'In stock'}</small></td><td>{x.supplier}</td><td>{currency(x.cost)}</td><td><button className="row-menu" onClick={()=>remove('inventory',x.name)}><Trash2 size={16}/></button></td></tr>)}</tbody></table></div></div><div className="wastage-banner"><div><AlertCircle size={18}/><div><b>Food wastage tracking</b><p>You saved 8.2 kg of food compared to last week. Keep it up!</p></div></div><button onClick={()=>toast('Wastage log opened')}>View wastage log <ArrowUpRight size={14}/></button></div></>}
function Reports({data}){return <><PageHead eyebrow="INSIGHTS & ANALYTICS" title="Reports" sub="A clear view of your operations, from the dining hall to the ledger." button="Export report" onClick={()=>exportCSV('mess-analytics.csv',[{report:'Daily attendance',value:'92%'},{report:'Monthly revenue',value:'₹6,25,000'},{report:'Active students',value:785},{report:'Open complaints',value:data.complaints.filter(c=>c.status!=='Resolved').length}])}/><div className="report-filters"><span><CalendarDays size={15}/> Date range</span><button>Nov 1, 2026 <span>to</span> Nov 10, 2026 <ChevronDown size={14}/></button><button onClick={()=>toast('Date range set to this month')}>This month</button></div><div className="stat-grid">{[['Attendance rate','92%','↑ 3.4%'],['Revenue collected','₹6,25,000','↑ 8.2%'],['Food consumed','1,248 kg','Across 4,892 meals'],['Student satisfaction','4.6 / 5','↑ 0.3 points']].map(([a,b,c],i)=><div className="stat-card" key={a}><div className="stat-top"><span>{a}</span><div className={`stat-icon ${['blue','teal','amber','violet'][i]}`}><BarChart3 size={17}/></div></div><div className="stat-value">{b}</div><div className="stat-bottom"><span className="trend">{c}</span></div></div>)}</div><div className="chart-grid"><div className="panel large-chart"><div className="panel-head"><div><h3>Revenue report</h3><p>Monthly collection · ₹ Lakhs</p></div><button className="icon-button" onClick={()=>exportCSV('revenue-report.csv',revenue)}><Download size={16}/></button></div><ResponsiveContainer width="100%" height={245}><BarChart data={revenue}><CartesianGrid stroke="#ffffff0c" vertical={false}/><XAxis dataKey="m" stroke="#7d879b" axisLine={false} tickLine={false}/><YAxis stroke="#7d879b" axisLine={false} tickLine={false}/><Tooltip/><Bar dataKey="v" fill="#34d6c5" radius={[6,6,0,0]}/></BarChart></ResponsiveContainer></div><div className="panel"><div className="panel-head"><div><h3>Report library</h3><p>Download detailed reports</p></div></div>{[['Daily attendance report','Updated today'],['Monthly revenue report','Updated Nov 1'],['Student statistics','Updated today'],['Food consumption report','Updated Nov 9']].map(([n,d],i)=><button className="report-item" key={n} onClick={()=>exportCSV(n.toLowerCase().replaceAll(' ','-')+'.csv',[{report:n,generated:d},{metric:'Total',value:i===0?'92%':'850'}])}><span className="report-icon"><FileText size={16}/></span><span><b>{n}</b><small>{d}</small></span><Download size={16}/></button>)}</div></div></>}
function SettingsPage({dark,setDark,onLogout}){const [fee,setFee]=useState('4500'),[name,setName]=useState('Admin Sahoo');return <><PageHead eyebrow="PREFERENCES" title="Settings" sub="Manage your account and configure campus mess preferences."/><div className="settings-grid"><div className="panel settings-panel"><div className="settings-title"><div className="avatar big">AS</div><div><h3>Administrator profile</h3><p>Your account and contact details</p></div></div><label className="form-field">Full name<input value={name} onChange={e=>setName(e.target.value)}/></label><label className="form-field">Email address<input defaultValue="admin@iiit-bh.ac.in" type="email"/></label><label className="form-field">Role<input defaultValue="Mess Administrator"/></label><div className="settings-buttons"><button className="primary" onClick={()=>toast.success('Profile updated')}>Save changes</button><button className="secondary" onClick={onLogout}>Sign out</button></div></div><div className="panel settings-panel"><h3>Mess configuration</h3><p>Institute and subscription details</p><label className="form-field">Mess name<input defaultValue="IIIT Bhubaneswar Central Mess"/></label><label className="form-field">Monthly mess fee (₹)<input value={fee} onChange={e=>setFee(e.target.value)} type="number"/></label><label className="form-field">Academic year<select defaultValue="2026-27"><option>2026-27</option><option>2025-26</option></select></label><button className="primary" onClick={()=>toast.success('Mess settings saved')}>Save configuration</button></div><div className="panel settings-panel"><h3>Appearance</h3><p>Personalize your dashboard experience</p><div className="setting-row"><div><b>Dark theme</b><small>Use the low-light interface</small></div><button className={`toggle ${dark?'on':''}`} onClick={()=>setDark(!dark)}><i/></button></div><div className="setting-row"><div><b>Email notifications</b><small>Get updates for new complaints</small></div><button className="toggle on" onClick={e=>e.currentTarget.classList.toggle('on')}><i/></button></div><div className="setting-row"><div><b>Low stock alerts</b><small>Notify when inventory runs low</small></div><button className="toggle on" onClick={e=>e.currentTarget.classList.toggle('on')}><i/></button></div></div><div className="panel settings-panel"><h3>Notifications</h3><p>Choose the updates you receive</p>{['New student registrations','Payment confirmations','New feedback submissions'].map(t=><div className="setting-row" key={t}><div><b>{t}</b><small>In-app notification</small></div><button className="toggle on" onClick={e=>e.currentTarget.classList.toggle('on')}><i/></button></div>)}</div></div></>}
function FormModal({modal,onClose,onSave}){const [vals,setVals]=useState(modal.item||{});const fields=modal.fields||[];const labels=modal.labels||fields;const input=(key,label)=>{const value=vals[key]??'';if(key==='subscription'||key==='payment'||key==='category'||key==='priority'||key==='meal'||key==='rating'||key==='day'||key==='unit'){let opts=key==='subscription'?['Active','Inactive']:key==='payment'?['Paid','Pending']:key==='category'?['Food Quality','Hygiene','Staff Behaviour','Menu Issues','Other']:key==='priority'?['Low','Medium','High']:key==='meal'?['Breakfast','Lunch','Snacks','Dinner']:key==='rating'?['5','4','3','2','1']:key==='day'?['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday']:key==='unit'?['kg','L','pcs','box']:[];return <select value={value||opts[0]} onChange={e=>setVals({...vals,[key]:e.target.value})}>{opts.map(o=><option key={o}>{o}</option>)}</select>}return <input required={['id','name','message','qty'].includes(key)} type={key==='email'?'email':key==='qty'||key==='cost'||key==='threshold'||key==='rating'?'number':'text'} placeholder={label} value={value} onChange={e=>setVals({...vals,[key]:e.target.value})}/>};return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><form className="modal" onSubmit={e=>{e.preventDefault();const result={...vals};if(modal.key==='students'){result.subscription||='Active';result.payment||='Paid'}if(modal.key==='complaints'){result.id=`CMP-${Math.floor(1100+Math.random()*800)}`;result.status='Pending';result.date='Today'}if(modal.key==='inventory'){result.qty=Number(result.qty);result.threshold=Number(result.threshold||0);result.cost=Number(result.cost||0)}if(modal.key==='feedback'){result.rating=Number(result.rating||5);result.date='Today'}if(modal.item){if(modal.key==='menu')onSave({...modal.item,...result});else onSave(result)}else onSave(result)}}><button type="button" className="modal-x" onClick={onClose}><X size={18}/></button><div className="eyebrow">SMART MESS · MANAGEMENT</div><h2>{modal.title}</h2><p className="modal-desc">Fill in the details below to keep your records up to date.</p><div className="form-grid">{fields.map((f,i)=><label className={`form-field ${f==='message'||f==='comment'? 'wide':''}`} key={f}>{labels[i]}{f==='message'||f==='comment'?<textarea required value={vals[f]||''} onChange={e=>setVals({...vals,[f]:e.target.value})}/>:input(f,labels[i])}</label>)}</div><div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancel</button><button className="primary" type="submit"><Check size={15}/>Save changes</button></div></form></div>}
function Drawer({item,setModal,onClose}){return <div className="drawer-wrap" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><aside className="drawer"><button className="modal-x" onClick={onClose}><X/></button>{item.type==='scanner'?<><div className="eyebrow">QUICK ACTION</div><h2>Scan attendance</h2><p>Use a student QR code for a fast mess check-in.</p><div className="scan-box"><QrCode size={90}/></div><button className="primary full" onClick={()=>toast.success('Aarav Mohanty checked in')}>Simulate check-in</button></>:<><div className="avatar big">{item.name.split(' ').map(x=>x[0]).slice(0,2).join('')}</div><div className="eyebrow">STUDENT PROFILE</div><h2>{item.name}</h2><p>{item.id}</p><div className="drawer-fields">{[['Email',item.email],['Phone',item.phone],['Department',item.department],['Hostel',item.hostel],['Room',item.room],['Mess subscription',item.subscription],['Payment status',item.payment]].map(([k,v])=><div key={k}><span>{k}</span><b>{v||'—'}</b></div>)}</div><button className="primary full" onClick={()=>{onClose();setModal({title:'Edit student',key:'students',item,fields:['id','name','email','phone','department','hostel','room','subscription','payment'],labels:['Student ID','Full name','Email','Phone','Department','Hostel','Room number','Subscription','Payment status']})}}>Edit student profile</button></>}</aside></div>}
export default App;
